--
-- Table structure for table `account_masters`
--

DROP TABLE IF EXISTS `account_masters`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `account_masters` (
  `id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL,
  `group_id` char(36) NOT NULL,
  `account_code` varchar(60) NOT NULL,
  `account_name` varchar(180) NOT NULL,
  `normal_balance` varchar(10) NOT NULL,
  `opening_debit` decimal(15,2) NOT NULL DEFAULT 0.00,
  `opening_credit` decimal(15,2) NOT NULL DEFAULT 0.00,
  `current_balance` decimal(15,2) NOT NULL DEFAULT 0.00,
  `is_control_account` tinyint(1) NOT NULL DEFAULT 0,
  `control_type` varchar(40) DEFAULT NULL,
  `is_system` tinyint(1) NOT NULL DEFAULT 0,
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE',
  `notes` text DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `account_masters_company_id_account_code_key` (`company_id`,`account_code`),
  KEY `account_masters_company_id_group_id_status_idx` (`company_id`,`group_id`,`status`),
  KEY `account_masters_company_id_control_type_idx` (`company_id`,`control_type`),
  KEY `account_masters_group_id_fkey` (`group_id`),
  CONSTRAINT `account_masters_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `account_masters_group_id_fkey` FOREIGN KEY (`group_id`) REFERENCES `account_groups` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

