--
-- Table structure for table `accounting_periods`
--

DROP TABLE IF EXISTS `accounting_periods`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `accounting_periods` (
  `id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL,
  `financial_year_id` char(36) NOT NULL,
  `period_name` varchar(50) NOT NULL,
  `period_code` varchar(20) NOT NULL,
  `period_number` int(11) NOT NULL,
  `start_date` datetime(3) NOT NULL,
  `end_date` datetime(3) NOT NULL,
  `is_closed` tinyint(1) NOT NULL DEFAULT 0,
  `closed_at` datetime(3) DEFAULT NULL,
  `closed_by_id` char(36) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `accounting_periods_company_id_financial_year_id_period_numbe_key` (`company_id`,`financial_year_id`,`period_number`),
  UNIQUE KEY `accounting_periods_company_id_period_code_key` (`company_id`,`period_code`),
  KEY `accounting_periods_company_id_is_closed_idx` (`company_id`,`is_closed`),
  KEY `accounting_periods_financial_year_id_fkey` (`financial_year_id`),
  CONSTRAINT `accounting_periods_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `accounting_periods_financial_year_id_fkey` FOREIGN KEY (`financial_year_id`) REFERENCES `financial_years` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

