--
-- Table structure for table `bank_accounts`
--

DROP TABLE IF EXISTS `bank_accounts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bank_accounts` (
  `id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL,
  `bank_name` varchar(120) NOT NULL,
  `account_holder_name` varchar(180) NOT NULL,
  `account_number` varchar(50) NOT NULL,
  `masked_account_number` varchar(50) DEFAULT NULL,
  `ifsc_code` varchar(30) NOT NULL,
  `branch_name` varchar(120) DEFAULT NULL,
  `account_type` varchar(30) NOT NULL DEFAULT 'CURRENT',
  `account_id` char(36) DEFAULT NULL,
  `opening_balance` decimal(15,2) NOT NULL DEFAULT 0.00,
  `current_balance` decimal(15,2) NOT NULL DEFAULT 0.00,
  `overdraft_limit` decimal(15,2) NOT NULL DEFAULT 0.00,
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE',
  `is_default` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `bank_accounts_company_id_account_number_key` (`company_id`,`account_number`),
  KEY `bank_accounts_company_id_status_idx` (`company_id`,`status`),
  KEY `bank_accounts_account_id_fkey` (`account_id`),
  CONSTRAINT `bank_accounts_account_id_fkey` FOREIGN KEY (`account_id`) REFERENCES `account_masters` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `bank_accounts_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

