--
-- Table structure for table `bank_reconciliation_items`
--

DROP TABLE IF EXISTS `bank_reconciliation_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bank_reconciliation_items` (
  `id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL,
  `reconciliation_id` char(36) NOT NULL,
  `bank_transaction_id` char(36) NOT NULL,
  `voucher_id` char(36) DEFAULT NULL,
  `voucher_item_id` char(36) DEFAULT NULL,
  `matched_amount` decimal(15,2) NOT NULL,
  `clearance_date` datetime(3) DEFAULT NULL,
  `match_type` varchar(30) NOT NULL DEFAULT 'EXACT',
  `notes` text DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `bank_reconciliation_items_reconciliation_id_bank_transaction_key` (`reconciliation_id`,`bank_transaction_id`),
  KEY `bank_reconciliation_items_company_id_bank_transaction_id_idx` (`company_id`,`bank_transaction_id`),
  KEY `bank_reconciliation_items_company_id_voucher_id_idx` (`company_id`,`voucher_id`),
  KEY `bank_reconciliation_items_company_id_voucher_item_id_idx` (`company_id`,`voucher_item_id`),
  KEY `bank_reconciliation_items_bank_transaction_id_fkey` (`bank_transaction_id`),
  KEY `bank_reconciliation_items_voucher_id_fkey` (`voucher_id`),
  KEY `bank_reconciliation_items_voucher_item_id_fkey` (`voucher_item_id`),
  CONSTRAINT `bank_reconciliation_items_bank_transaction_id_fkey` FOREIGN KEY (`bank_transaction_id`) REFERENCES `bank_transactions` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `bank_reconciliation_items_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `bank_reconciliation_items_reconciliation_id_fkey` FOREIGN KEY (`reconciliation_id`) REFERENCES `bank_reconciliations` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `bank_reconciliation_items_voucher_id_fkey` FOREIGN KEY (`voucher_id`) REFERENCES `journal_vouchers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `bank_reconciliation_items_voucher_item_id_fkey` FOREIGN KEY (`voucher_item_id`) REFERENCES `journal_voucher_items` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `bank_reconciliation_items`
--

