/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bank_transactions` (
  `id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL,
  `bank_account_id` char(36) NOT NULL,
  `transaction_date` datetime(3) NOT NULL,
  `value_date` datetime(3) DEFAULT NULL,
  `reference_no` varchar(100) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `debit_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `credit_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `running_balance` decimal(15,2) DEFAULT NULL,
  `import_source` varchar(50) DEFAULT 'MANUAL',
  `reconciliation_status` varchar(30) NOT NULL DEFAULT 'UNRECONCILED',
  `matched_voucher_id` char(36) DEFAULT NULL,
  `reconciliation_id` char(36) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  `external_ref` varchar(120) DEFAULT NULL,
  `statement_batch_id` varchar(60) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `bank_transactions_company_id_bank_account_id_external_ref_key` (`company_id`,`bank_account_id`,`external_ref`),
  KEY `bank_transactions_company_id_bank_account_id_transaction_dat_idx` (`company_id`,`bank_account_id`,`transaction_date`),
  KEY `bank_transactions_company_id_bank_account_id_reconciliation__idx` (`company_id`,`bank_account_id`,`reconciliation_status`),
  KEY `bank_transactions_bank_account_id_fkey` (`bank_account_id`),
  KEY `bank_transactions_reconciliation_id_fkey` (`reconciliation_id`),
  KEY `bank_transactions_company_id_bank_account_id_reference_no_idx` (`company_id`,`bank_account_id`,`reference_no`),
  CONSTRAINT `bank_transactions_bank_account_id_fkey` FOREIGN KEY (`bank_account_id`) REFERENCES `bank_accounts` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `bank_transactions_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `bank_transactions_reconciliation_id_fkey` FOREIGN KEY (`reconciliation_id`) REFERENCES `bank_reconciliations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

