--
-- Table structure for table `customer_return_inspections`
--

DROP TABLE IF EXISTS `customer_return_inspections`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `customer_return_inspections` (
  `id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL,
  `inspection_no` varchar(60) NOT NULL,
  `customer_return_id` char(36) NOT NULL,
  `customer_return_item_id` char(36) NOT NULL,
  `sku` varchar(80) NOT NULL,
  `inspected_qty` decimal(12,4) NOT NULL DEFAULT 0.0000,
  `restock_qty` decimal(12,4) NOT NULL DEFAULT 0.0000,
  `rework_qty` decimal(12,4) NOT NULL DEFAULT 0.0000,
  `reject_qty` decimal(12,4) NOT NULL DEFAULT 0.0000,
  `scrap_qty` decimal(12,4) NOT NULL DEFAULT 0.0000,
  `target_warehouse_id` char(36) DEFAULT NULL,
  `restock_batch_id` char(36) DEFAULT NULL,
  `restock_batch_no` varchar(80) DEFAULT NULL,
  `inventory_movement_id` char(36) DEFAULT NULL,
  `qc_findings` text DEFAULT NULL,
  `disposition` varchar(50) NOT NULL,
  `inspected_by` varchar(120) NOT NULL,
  `inspection_date` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `status` varchar(40) NOT NULL DEFAULT 'COMPLETED',
  `notes` text DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `customer_return_inspections_company_id_inspection_no_key` (`company_id`,`inspection_no`),
  KEY `customer_return_inspections_company_id_customer_return_id_idx` (`company_id`,`customer_return_id`),
  KEY `customer_return_inspections_company_id_customer_return_item__idx` (`company_id`,`customer_return_item_id`),
  KEY `customer_return_inspections_company_id_sku_idx` (`company_id`,`sku`),
  KEY `customer_return_inspections_customer_return_id_fkey` (`customer_return_id`),
  KEY `customer_return_inspections_customer_return_item_id_fkey` (`customer_return_item_id`),
  KEY `customer_return_inspections_target_warehouse_id_fkey` (`target_warehouse_id`),
  KEY `customer_return_inspections_restock_batch_id_fkey` (`restock_batch_id`),
  CONSTRAINT `customer_return_inspections_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `customer_return_inspections_customer_return_id_fkey` FOREIGN KEY (`customer_return_id`) REFERENCES `customer_returns` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `customer_return_inspections_customer_return_item_id_fkey` FOREIGN KEY (`customer_return_item_id`) REFERENCES `customer_return_items` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `customer_return_inspections_restock_batch_id_fkey` FOREIGN KEY (`restock_batch_id`) REFERENCES `inventory_batches` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `customer_return_inspections_target_warehouse_id_fkey` FOREIGN KEY (`target_warehouse_id`) REFERENCES `inventory_warehouses` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

