--
-- Table structure for table `customer_return_items`
--

DROP TABLE IF EXISTS `customer_return_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `customer_return_items` (
  `id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL,
  `customer_return_id` char(36) NOT NULL,
  `dispatch_order_item_id` char(36) DEFAULT NULL,
  `product_id` char(36) DEFAULT NULL,
  `sku` varchar(80) NOT NULL,
  `product_name` varchar(180) NOT NULL,
  `uom` varchar(20) NOT NULL DEFAULT 'PCS',
  `return_qty` decimal(12,4) NOT NULL DEFAULT 0.0000,
  `received_qty` decimal(12,4) NOT NULL DEFAULT 0.0000,
  `unit_price` decimal(15,2) NOT NULL DEFAULT 0.00,
  `total_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `return_reason` varchar(100) DEFAULT NULL,
  `condition_on_arrival` varchar(50) DEFAULT NULL,
  `inspected_qty` decimal(12,4) NOT NULL DEFAULT 0.0000,
  `status` varchar(50) NOT NULL DEFAULT 'PENDING_RECEIPT',
  `notes` text DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `customer_return_items_company_id_customer_return_id_idx` (`company_id`,`customer_return_id`),
  KEY `customer_return_items_company_id_product_id_idx` (`company_id`,`product_id`),
  KEY `customer_return_items_company_id_sku_idx` (`company_id`,`sku`),
  KEY `customer_return_items_customer_return_id_fkey` (`customer_return_id`),
  KEY `customer_return_items_dispatch_order_item_id_fkey` (`dispatch_order_item_id`),
  KEY `customer_return_items_product_id_fkey` (`product_id`),
  CONSTRAINT `customer_return_items_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `customer_return_items_customer_return_id_fkey` FOREIGN KEY (`customer_return_id`) REFERENCES `customer_returns` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `customer_return_items_dispatch_order_item_id_fkey` FOREIGN KEY (`dispatch_order_item_id`) REFERENCES `dispatch_order_items` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `customer_return_items_product_id_fkey` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

