--
-- Table structure for table `customer_returns`
--

DROP TABLE IF EXISTS `customer_returns`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `customer_returns` (
  `id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL,
  `rma_no` varchar(60) NOT NULL,
  `dispatch_order_id` char(36) DEFAULT NULL,
  `dispatch_no` varchar(60) DEFAULT NULL,
  `sales_order_id` char(36) DEFAULT NULL,
  `sales_order_no` varchar(60) DEFAULT NULL,
  `customer_id` char(36) DEFAULT NULL,
  `customer_name` varchar(180) NOT NULL,
  `customer_phone` varchar(40) DEFAULT NULL,
  `customer_email` varchar(120) DEFAULT NULL,
  `request_date` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `status` varchar(50) NOT NULL DEFAULT 'REQUESTED',
  `return_reason` varchar(100) NOT NULL,
  `reason_details` text DEFAULT NULL,
  `total_returned_qty` decimal(12,4) NOT NULL DEFAULT 0.0000,
  `total_returned_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `pickup_address` text DEFAULT NULL,
  `receiving_warehouse_id` char(36) DEFAULT NULL,
  `approved_at` datetime(3) DEFAULT NULL,
  `approved_by_id` char(36) DEFAULT NULL,
  `received_at` datetime(3) DEFAULT NULL,
  `received_by_id` char(36) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metadata`)),
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `customer_returns_company_id_rma_no_key` (`company_id`,`rma_no`),
  KEY `customer_returns_company_id_status_request_date_idx` (`company_id`,`status`,`request_date`),
  KEY `customer_returns_company_id_dispatch_order_id_idx` (`company_id`,`dispatch_order_id`),
  KEY `customer_returns_company_id_customer_id_idx` (`company_id`,`customer_id`),
  KEY `customer_returns_dispatch_order_id_fkey` (`dispatch_order_id`),
  KEY `customer_returns_sales_order_id_fkey` (`sales_order_id`),
  KEY `customer_returns_customer_id_fkey` (`customer_id`),
  KEY `customer_returns_receiving_warehouse_id_fkey` (`receiving_warehouse_id`),
