--
-- Table structure for table `dispatch_order_items`
--

DROP TABLE IF EXISTS `dispatch_order_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `dispatch_order_items` (
  `id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL,
  `dispatch_order_id` char(36) NOT NULL,
  `product_id` char(36) DEFAULT NULL,
  `sku` varchar(80) NOT NULL,
  `product_name` varchar(180) NOT NULL,
  `uom` varchar(20) NOT NULL DEFAULT 'PCS',
  `ordered_qty` decimal(12,4) NOT NULL DEFAULT 0.0000,
  `dispatched_qty` decimal(12,4) NOT NULL DEFAULT 0.0000,
  `unit_price` decimal(15,2) NOT NULL DEFAULT 0.00,
  `total_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `tax_rate` decimal(5,2) NOT NULL DEFAULT 0.00,
  `tax_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `gross_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `hsn_code` varchar(30) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `dispatch_order_items_company_id_dispatch_order_id_idx` (`company_id`,`dispatch_order_id`),
  KEY `dispatch_order_items_company_id_product_id_idx` (`company_id`,`product_id`),
  KEY `dispatch_order_items_company_id_sku_idx` (`company_id`,`sku`),
  KEY `dispatch_order_items_dispatch_order_id_fkey` (`dispatch_order_id`),
  KEY `dispatch_order_items_product_id_fkey` (`product_id`),
  CONSTRAINT `dispatch_order_items_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `dispatch_order_items_dispatch_order_id_fkey` FOREIGN KEY (`dispatch_order_id`) REFERENCES `dispatch_orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `dispatch_order_items_product_id_fkey` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

