--
-- Table structure for table `dispatch_orders`
--

DROP TABLE IF EXISTS `dispatch_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `dispatch_orders` (
  `id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL,
  `dispatch_no` varchar(60) NOT NULL,
  `sales_order_id` char(36) DEFAULT NULL,
  `sales_order_no` varchar(60) DEFAULT NULL,
  `customer_id` char(36) DEFAULT NULL,
  `customer_name` varchar(180) NOT NULL,
  `customer_gstin` varchar(20) DEFAULT NULL,
  `shipping_address` text DEFAULT NULL,
  `billing_address` text DEFAULT NULL,
  `dispatch_date` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `status` varchar(50) NOT NULL DEFAULT 'DRAFT',
  `fulfillment_type` varchar(30) NOT NULL DEFAULT 'FULL',
  `warehouse_id` char(36) DEFAULT NULL,
  `warehouse_name` varchar(120) DEFAULT NULL,
  `carrier_name` varchar(120) DEFAULT NULL,
  `tracking_no` varchar(100) DEFAULT NULL,
  `vehicle_no` varchar(40) DEFAULT NULL,
  `driver_name` varchar(120) DEFAULT NULL,
  `driver_phone` varchar(40) DEFAULT NULL,
  `eway_bill_no` varchar(60) DEFAULT NULL,
  `eway_bill_date` datetime(3) DEFAULT NULL,
  `eway_bill_valid_till` datetime(3) DEFAULT NULL,
  `invoice_no` varchar(60) DEFAULT NULL,
  `invoice_date` datetime(3) DEFAULT NULL,
  `total_packages` int(11) NOT NULL DEFAULT 1,
  `total_gross_weight_kg` decimal(12,4) NOT NULL DEFAULT 0.0000,
  `total_net_weight_kg` decimal(12,4) NOT NULL DEFAULT 0.0000,
  `total_dispatched_qty` decimal(12,4) NOT NULL DEFAULT 0.0000,
  `total_dispatched_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `gate_pass_id` char(36) DEFAULT NULL,
  `gate_pass_no` varchar(60) DEFAULT NULL,
  `dispatched_at` datetime(3) DEFAULT NULL,
  `dispatched_by_id` char(36) DEFAULT NULL,
  `delivered_at` datetime(3) DEFAULT NULL,
  `delivered_by_id` char(36) DEFAULT NULL,
  `pod_attachment_url` varchar(255) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metadata`)),
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `dispatch_orders_company_id_dispatch_no_key` (`company_id`,`dispatch_no`),
  KEY `dispatch_orders_company_id_status_dispatch_date_idx` (`company_id`,`status`,`dispatch_date`),
  KEY `dispatch_orders_company_id_sales_order_id_idx` (`company_id`,`sales_order_id`),
  KEY `dispatch_orders_company_id_customer_id_idx` (`company_id`,`customer_id`),
  KEY `dispatch_orders_company_id_tracking_no_idx` (`company_id`,`tracking_no`),
  KEY `dispatch_orders_sales_order_id_fkey` (`sales_order_id`),
  KEY `dispatch_orders_customer_id_fkey` (`customer_id`),
  KEY `dispatch_orders_warehouse_id_fkey` (`warehouse_id`),
  CONSTRAINT `dispatch_orders_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `dispatch_orders_customer_id_fkey` FOREIGN KEY (`customer_id`) REFERENCES `crm_customers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `dispatch_orders_sales_order_id_fkey` FOREIGN KEY (`sales_order_id`) REFERENCES `sales_orders` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `dispatch_orders_warehouse_id_fkey` FOREIGN KEY (`warehouse_id`) REFERENCES `inventory_warehouses` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

