--
-- Table structure for table `dispatch_packages`
--

DROP TABLE IF EXISTS `dispatch_packages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `dispatch_packages` (
  `id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL,
  `dispatch_order_id` char(36) NOT NULL,
  `package_number` int(11) NOT NULL,
  `package_code` varchar(60) NOT NULL,
  `box_type` varchar(50) DEFAULT NULL,
  `length_cm` decimal(10,2) DEFAULT NULL,
  `width_cm` decimal(10,2) DEFAULT NULL,
  `height_cm` decimal(10,2) DEFAULT NULL,
  `weight_gross_kg` decimal(10,4) NOT NULL DEFAULT 0.0000,
  `weight_net_kg` decimal(10,4) NOT NULL DEFAULT 0.0000,
  `barcode` varchar(100) DEFAULT NULL,
  `item_details` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`item_details`)),
  `notes` text DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `dispatch_packages_dispatch_order_id_package_number_key` (`dispatch_order_id`,`package_number`),
  KEY `dispatch_packages_company_id_dispatch_order_id_idx` (`company_id`,`dispatch_order_id`),
  KEY `dispatch_packages_company_id_package_code_idx` (`company_id`,`package_code`),
  CONSTRAINT `dispatch_packages_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `dispatch_packages_dispatch_order_id_fkey` FOREIGN KEY (`dispatch_order_id`) REFERENCES `dispatch_orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

