--
-- Table structure for table `dispatch_trackings`
--

DROP TABLE IF EXISTS `dispatch_trackings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `dispatch_trackings` (
  `id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL,
  `dispatch_order_id` char(36) NOT NULL,
  `event_date` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `status` varchar(50) NOT NULL,
  `location` varchar(150) DEFAULT NULL,
  `carrier_status` varchar(100) DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `recorded_by` varchar(120) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  KEY `dispatch_trackings_company_id_dispatch_order_id_idx` (`company_id`,`dispatch_order_id`),
  KEY `dispatch_trackings_company_id_status_event_date_idx` (`company_id`,`status`,`event_date`),
  KEY `dispatch_trackings_dispatch_order_id_fkey` (`dispatch_order_id`),
  CONSTRAINT `dispatch_trackings_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `dispatch_trackings_dispatch_order_id_fkey` FOREIGN KEY (`dispatch_order_id`) REFERENCES `dispatch_orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `dispatch_trackings`
--

LOCK TABLES `dispatch_trackings` WRITE;
/*!40000 ALTER TABLE `dispatch_trackings` DISABLE KEYS */;
