--
-- Table structure for table `inventory_transfers`
--

DROP TABLE IF EXISTS `inventory_transfers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `inventory_transfers` (
  `id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL,
  `transfer_no` varchar(60) NOT NULL,
  `from_warehouse` varchar(120) NOT NULL,
  `to_warehouse` varchar(120) NOT NULL,
  `items` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`items`)),
  `status` varchar(40) NOT NULL DEFAULT 'IN_TRANSIT',
  `notes` text DEFAULT NULL,
  `dispatched_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `received_at` datetime(3) DEFAULT NULL,
  `created_by` varchar(150) DEFAULT NULL,
  `received_by` varchar(150) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `inventory_transfers_company_id_transfer_no_key` (`company_id`,`transfer_no`),
  KEY `inventory_transfers_company_id_status_created_at_idx` (`company_id`,`status`,`created_at`),
  CONSTRAINT `inventory_transfers_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

