--
-- Table structure for table `journal_vouchers`
--

DROP TABLE IF EXISTS `journal_vouchers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `journal_vouchers` (
  `id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL,
  `voucher_no` varchar(60) NOT NULL,
  `voucher_date` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `voucher_type` varchar(30) NOT NULL,
  `financial_year_id` char(36) DEFAULT NULL,
  `accounting_period_id` char(36) DEFAULT NULL,
  `reference_type` varchar(50) DEFAULT NULL,
  `reference_id` char(36) DEFAULT NULL,
  `reference_no` varchar(80) DEFAULT NULL,
  `narration` text DEFAULT NULL,
  `total_debit` decimal(15,2) NOT NULL DEFAULT 0.00,
  `total_credit` decimal(15,2) NOT NULL DEFAULT 0.00,
  `status` varchar(30) NOT NULL DEFAULT 'DRAFT',
  `is_reversal` tinyint(1) NOT NULL DEFAULT 0,
  `reversal_of_voucher_id` char(36) DEFAULT NULL,
  `posted_at` datetime(3) DEFAULT NULL,
  `posted_by_id` char(36) DEFAULT NULL,
  `posted_by_name` varchar(180) DEFAULT NULL,
  `created_by_id` char(36) DEFAULT NULL,
  `created_by_name` varchar(180) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `journal_vouchers_company_id_voucher_no_key` (`company_id`,`voucher_no`),
  KEY `journal_vouchers_company_id_voucher_date_voucher_type_status_idx` (`company_id`,`voucher_date`,`voucher_type`,`status`),
  KEY `journal_vouchers_company_id_reference_type_reference_id_idx` (`company_id`,`reference_type`,`reference_id`),
  KEY `journal_vouchers_financial_year_id_fkey` (`financial_year_id`),
  KEY `journal_vouchers_accounting_period_id_fkey` (`accounting_period_id`),
  KEY `journal_vouchers_reversal_of_voucher_id_fkey` (`reversal_of_voucher_id`),
  CONSTRAINT `journal_vouchers_accounting_period_id_fkey` FOREIGN KEY (`accounting_period_id`) REFERENCES `accounting_periods` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `journal_vouchers_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `journal_vouchers_financial_year_id_fkey` FOREIGN KEY (`financial_year_id`) REFERENCES `financial_years` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `journal_vouchers_reversal_of_voucher_id_fkey` FOREIGN KEY (`reversal_of_voucher_id`) REFERENCES `journal_vouchers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

