--
-- Table structure for table `payment_allocations`
--

DROP TABLE IF EXISTS `payment_allocations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `payment_allocations` (
  `id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL,
  `payment_receipt_id` char(36) NOT NULL,
  `invoice_id` char(36) DEFAULT NULL,
  `bill_id` char(36) DEFAULT NULL,
  `allocated_amount` decimal(15,2) NOT NULL,
  `allocation_date` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE',
  `notes` text DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  `target_type` varchar(30) NOT NULL DEFAULT 'SALES_INVOICE',
  PRIMARY KEY (`id`),
  KEY `payment_allocations_company_id_payment_receipt_id_idx` (`company_id`,`payment_receipt_id`),
  KEY `payment_allocations_company_id_invoice_id_idx` (`company_id`,`invoice_id`),
  KEY `payment_allocations_company_id_bill_id_idx` (`company_id`,`bill_id`),
  KEY `payment_allocations_payment_receipt_id_fkey` (`payment_receipt_id`),
  KEY `payment_allocations_invoice_id_fkey` (`invoice_id`),
