--
-- Table structure for table `payment_receipts`
--

DROP TABLE IF EXISTS `payment_receipts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `payment_receipts` (
  `id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL,
  `payment_receipt_no` varchar(60) NOT NULL,
  `payment_type` varchar(30) NOT NULL,
  `customer_id` char(36) DEFAULT NULL,
  `vendor_id` char(36) DEFAULT NULL,
  `payment_mode` varchar(30) NOT NULL DEFAULT 'BANK',
  `amount` decimal(15,2) NOT NULL,
  `unallocated_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `payment_date` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `bank_account_id` char(36) DEFAULT NULL,
  `cheque_reference_no` varchar(100) DEFAULT NULL,
  `cheque_date` datetime(3) DEFAULT NULL,
  `financial_year_id` char(36) DEFAULT NULL,
  `accounting_period_id` char(36) DEFAULT NULL,
  `voucher_id` char(36) DEFAULT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'DRAFT',
  `notes` text DEFAULT NULL,
  `created_by_id` char(36) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `payment_receipts_company_id_payment_receipt_no_key` (`company_id`,`payment_receipt_no`),
  KEY `payment_receipts_company_id_payment_type_status_payment_date_idx` (`company_id`,`payment_type`,`status`,`payment_date`),
  KEY `payment_receipts_company_id_customer_id_idx` (`company_id`,`customer_id`),
  KEY `payment_receipts_company_id_vendor_id_idx` (`company_id`,`vendor_id`),
  KEY `payment_receipts_customer_id_fkey` (`customer_id`),
  KEY `payment_receipts_vendor_id_fkey` (`vendor_id`),
  KEY `payment_receipts_bank_account_id_fkey` (`bank_account_id`),
  KEY `payment_receipts_voucher_id_fkey` (`voucher_id`),
  CONSTRAINT `payment_receipts_bank_account_id_fkey` FOREIGN KEY (`bank_account_id`) REFERENCES `bank_accounts` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `payment_receipts_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `payment_receipts_customer_id_fkey` FOREIGN KEY (`customer_id`) REFERENCES `crm_customers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `payment_receipts_vendor_id_fkey` FOREIGN KEY (`vendor_id`) REFERENCES `vendors` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `payment_receipts_voucher_id_fkey` FOREIGN KEY (`voucher_id`) REFERENCES `journal_vouchers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

