--
-- Table structure for table `purchase_quotations`
--

DROP TABLE IF EXISTS `purchase_quotations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `purchase_quotations` (
  `id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL,
  `request_id` char(36) NOT NULL,
  `vendor_id` char(36) NOT NULL,
  `quote_no` varchar(60) NOT NULL,
  `vendor_quote_no` varchar(80) DEFAULT NULL,
  `quote_date` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `valid_until` datetime(3) DEFAULT NULL,
  `items` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`items`)),
  `subtotal` decimal(15,2) NOT NULL DEFAULT 0.00,
  `tax_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `freight_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `loading_charges` decimal(15,2) NOT NULL DEFAULT 0.00,
  `unloading_charges` decimal(15,2) NOT NULL DEFAULT 0.00,
  `handling_charges` decimal(15,2) NOT NULL DEFAULT 0.00,
  `other_charges` decimal(15,2) NOT NULL DEFAULT 0.00,
  `landed_cost` decimal(15,2) NOT NULL DEFAULT 0.00,
  `total_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `delivery_days` int(11) NOT NULL DEFAULT 7,
  `payment_terms` varchar(100) DEFAULT NULL,
  `transporter_responsibility` varchar(40) NOT NULL DEFAULT 'SUPPLIER',
  `is_lowest_landed_cost` tinyint(1) NOT NULL DEFAULT 0,
  `non_lowest_justification` text DEFAULT NULL,
  `is_exception_approved` tinyint(1) NOT NULL DEFAULT 0,
  `exception_reason` text DEFAULT NULL,
  `exception_approved_by_id` char(36) DEFAULT NULL,
  `status` varchar(40) NOT NULL DEFAULT 'RECEIVED',
  `notes` text DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
