--
-- Table structure for table `purchase_receipts`
--

DROP TABLE IF EXISTS `purchase_receipts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `purchase_receipts` (
  `id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL,
  `order_id` char(36) NOT NULL,
  `grn_no` varchar(60) NOT NULL,
  `warehouse` varchar(120) NOT NULL,
  `vehicle_no` varchar(50) DEFAULT NULL,
  `delivery_challan_no` varchar(80) DEFAULT NULL,
  `carrier_name` varchar(120) DEFAULT NULL,
  `challan_date` datetime(3) DEFAULT NULL,
  `items` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`items`)),
  `received_qty` int(11) NOT NULL DEFAULT 0,
  `accepted_qty` int(11) NOT NULL DEFAULT 0,
  `rejected_qty` int(11) NOT NULL DEFAULT 0,
  `short_qty` int(11) NOT NULL DEFAULT 0,
  `damaged_qty` int(11) NOT NULL DEFAULT 0,
  `qc_status` varchar(40) NOT NULL DEFAULT 'PASSED',
  `inspection_remarks` text DEFAULT NULL,
  `inspector_id` char(36) DEFAULT NULL,
  `inspector_name` varchar(180) DEFAULT NULL,
  `inspected_at` datetime(3) DEFAULT NULL,
  `received_by` varchar(150) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `received_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `purchase_receipts_company_id_grn_no_key` (`company_id`,`grn_no`),
  KEY `purchase_receipts_company_id_qc_status_received_at_idx` (`company_id`,`qc_status`,`received_at`),
  KEY `purchase_receipts_order_id_received_at_idx` (`order_id`,`received_at`),
  CONSTRAINT `purchase_receipts_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `purchase_receipts_order_id_fkey` FOREIGN KEY (`order_id`) REFERENCES `purchase_orders` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

