--
-- Table structure for table `vendor_debit_notes`
--

DROP TABLE IF EXISTS `vendor_debit_notes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `vendor_debit_notes` (
  `id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL,
  `debit_note_no` varchar(60) NOT NULL,
  `vendor_id` char(36) NOT NULL,
  `purchase_bill_id` char(36) DEFAULT NULL,
  `job_work_reconciliation_id` char(36) DEFAULT NULL,
  `financial_year_id` char(36) DEFAULT NULL,
  `debit_note_date` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `taxable_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `cgst_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `sgst_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `igst_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `total_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `reason` varchar(255) DEFAULT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'DRAFT',
  `voucher_id` char(36) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `vendor_debit_notes_company_id_debit_note_no_key` (`company_id`,`debit_note_no`),
  KEY `vendor_debit_notes_company_id_vendor_id_status_idx` (`company_id`,`vendor_id`,`status`),
  KEY `vendor_debit_notes_vendor_id_fkey` (`vendor_id`),
  KEY `vendor_debit_notes_purchase_bill_id_fkey` (`purchase_bill_id`),
  KEY `vendor_debit_notes_job_work_reconciliation_id_fkey` (`job_work_reconciliation_id`),
  KEY `vendor_debit_notes_voucher_id_fkey` (`voucher_id`),
  CONSTRAINT `vendor_debit_notes_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `vendor_debit_notes_job_work_reconciliation_id_fkey` FOREIGN KEY (`job_work_reconciliation_id`) REFERENCES `job_work_reconciliations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `vendor_debit_notes_purchase_bill_id_fkey` FOREIGN KEY (`purchase_bill_id`) REFERENCES `purchase_bills` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `vendor_debit_notes_vendor_id_fkey` FOREIGN KEY (`vendor_id`) REFERENCES `vendors` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `vendor_debit_notes_voucher_id_fkey` FOREIGN KEY (`voucher_id`) REFERENCES `journal_vouchers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

